private static void fabricIteration(List<Bone> bones, PointF b, PointF target) {
    PointF pointF;
    PointF pointF2;
    UPoint uPoint = bones.get(0).end;
    UPoint uPoint2 = bones.get(bones.size() - 1).start;
    uPoint.x = target.x;
    uPoint.y = target.y;
    uPoint.orientation = bones.get(0).orientation();
    for (Bone bone : bones) {
        bone.start.orientation = bone.orientation();
        if (bone.end.minConstraintMet() && bone.end.maxConstraintMet()) {
            float fDistance = bone.originalLength / bone.start.distance(bone.end);
            float f = 1.0f - fDistance;
            bone.start.x = (bone.end.x * f) + (bone.start.x * fDistance);
            bone.start.y = (f * bone.end.y) + (fDistance * bone.start.y);
        } else {
            if (!bone.end.maxConstraintMet()) {
                double dNormalizeAngle = MathUtils.normalizeAngle(bone.end.orientation - bone.end.getMaxRotation(), 0.0f);
                pointF2 = new PointF(-((float) Math.cos(dNormalizeAngle)), -((float) Math.sin(dNormalizeAngle)));
            } else if (!bone.end.minConstraintMet()) {
                double dNormalizeAngle2 = MathUtils.normalizeAngle(bone.end.orientation - bone.end.getMinRotation(), 0.0f);
                pointF2 = new PointF(-((float) Math.cos(dNormalizeAngle2)), -((float) Math.sin(dNormalizeAngle2)));
            } else {
                throw new AssertionError("Unexpected rotation state: " + bone.end);
            }
            bone.start.x = bone.end.x + (pointF2.x * bone.originalLength);
            bone.start.y = bone.end.y + (pointF2.y * bone.originalLength);
            bone.start.orientation = bone.orientation();
            if (!bone.end.maxConstraintMet() || !bone.end.minConstraintMet()) {
                throw new AssertionError("Constraint still violated after forward adjustment rotation=" + bone.end.rotation() + ", updated bone=" + bone);
            }
        }
        bone.start.orientation = bone.orientation();
        if (!bone.end.maxConstraintMet() || !bone.end.minConstraintMet()) {
            throw new AssertionError("Constraint still violated after forward adjustment rotation=" + bone.end.rotation() + ", updated bone=" + bone);
        }
    }
    uPoint2.x = b.x;
    uPoint2.y = b.y;
    ListIterator<Bone> listIterator = bones.listIterator(bones.size());
    while (listIterator.hasPrevious()) {
        Bone bonePrevious = listIterator.previous();
        bonePrevious.start.orientation = bonePrevious.orientation();
        if (bonePrevious.start.minConstraintMet() && bonePrevious.start.maxConstraintMet()) {
            float fDistance2 = bonePrevious.originalLength / bonePrevious.start.distance(bonePrevious.end);
            float f2 = 1.0f - fDistance2;
            bonePrevious.end.x = (bonePrevious.start.x * f2) + (bonePrevious.end.x * fDistance2);
            bonePrevious.end.y = (f2 * bonePrevious.start.y) + (fDistance2 * bonePrevious.end.y);
        } else {
            if (bonePrevious.start == uPoint2) {
                throw new AssertionError("Orientation constraint triggered on the root node");
            }
            if (!bonePrevious.start.maxConstraintMet()) {
                double dNormalizeAngle3 = MathUtils.normalizeAngle(bonePrevious.start.getParent().orientation + bonePrevious.start.getMaxRotation(), 0.0f);
                pointF = new PointF((float) Math.cos(dNormalizeAngle3), (float) Math.sin(dNormalizeAngle3));
            } else if (!bonePrevious.start.minConstraintMet()) {
                double dNormalizeAngle4 = MathUtils.normalizeAngle(bonePrevious.start.getParent().orientation + bonePrevious.start.getMinRotation(), 0.0f);
                pointF = new PointF((float) Math.cos(dNormalizeAngle4), (float) Math.sin(dNormalizeAngle4));
            } else {
                throw new AssertionError("Unexpected rotation state: " + bonePrevious.end);
            }
            bonePrevious.end.x = bonePrevious.start.x + (pointF.x * bonePrevious.originalLength);
            bonePrevious.end.y = bonePrevious.start.y + (pointF.y * bonePrevious.originalLength);
        }
        bonePrevious.start.orientation = bonePrevious.orientation();
        if (!bonePrevious.start.maxConstraintMet() || !bonePrevious.start.minConstraintMet()) {
            throw new AssertionError("Constraint still violated after backward adjustment rotation=" + bonePrevious.start.rotation() + ", updated bone=" + bonePrevious);
        }
    }
}
